REGISTRY = {}

def register(name, callable = nil, &block)
  REGISTRY[name] = callable || block
end

def create(name)
  builder = REGISTRY.fetch(name) { raise KeyError, "unknown: #{name} (have #{REGISTRY.keys.join(', ')})" }
  builder.is_a?(Class) ? builder.new : builder.call
end

register(:sword) { Sword.new(damage: 10) }
